"use client";

import { useScrollProgress } from "@/hooks/useScrollProgress";

export default function GrowthMeter() {
  const progress = useScrollProgress();
  const pct = Math.round(progress * 100);

  return (
    <div className="fixed bottom-6 right-6 z-[9997] hidden md:block">
      <div className="bg-[#111111] border border-white/10 rounded-xl p-4 min-w-[180px] backdrop-blur-xl">
        <div className="text-[10px] uppercase tracking-widest text-[#8B8B8B] mb-2 font-mono">
          Growth Progress
        </div>
        <div className="flex gap-[2px] mb-2">
          {Array.from({ length: 10 }).map((_, i) => (
            <div
              key={i}
              className={`h-1.5 flex-1 rounded-full transition-all duration-300 ${
                i < Math.floor(progress * 10)
                  ? "bg-[#A3FF3F]"
                  : "bg-white/10"
              }`}
            />
          ))}
        </div>
        <div className="flex items-center justify-between">
          <span className="text-[11px] text-[#8B8B8B]">Growth</span>
          <span className="text-sm font-mono text-[#A3FF3F] font-bold">
            {pct}%
          </span>
        </div>
        <div className="flex gap-3 mt-2 text-[9px] uppercase tracking-widest text-white/30">
          <span>Design</span>
          <span>Develop</span>
          <span>Launch</span>
        </div>
      </div>
    </div>
  );
}
