"use client";

import { useRef, useEffect, useState } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

gsap.registerPlugin(ScrollTrigger);

const stats = [
  { value: 25, suffix: "+", label: "Projects" },
  { value: 98, suffix: "%", label: "Client Satisfaction" },
  { value: 4, suffix: "x", label: "Average Growth" },
  { value: 100, suffix: "%", label: "Custom Design" },
];

function AnimatedNumber({ target, suffix }: { target: number; suffix: string }) {
  const [count, setCount] = useState(0);
  const ref = useRef<HTMLSpanElement>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    const ctx = gsap.context(() => {
      gsap.fromTo(
        el,
        { textContent: 0 },
        {
          textContent: target,
          duration: 2,
          ease: "power2.out",
          snap: { textContent: 1 },
          scrollTrigger: {
            trigger: el,
            start: "top 85%",
            toggleActions: "play none none reverse",
          },
          onUpdate: function () {
            setCount(Math.round(Number(this.targets()[0].textContent)));
          },
        }
      );
    });

    return () => ctx.revert();
  }, [target]);

  return (
    <span ref={ref}>
      {count}
      {suffix}
    </span>
  );
}

export default function Numbers() {
  const containerRef = useRef<HTMLDivElement>(null);

  return (
    <section
      ref={containerRef}
      className="relative px-6 md:px-16 py-24 border-t border-white/5"
    >
      <div className="max-w-7xl mx-auto">
        <span className="text-[11px] uppercase tracking-[0.3em] text-[#8B8B8B] font-mono">
          By the Numbers
        </span>

        <div className="grid grid-cols-2 lg:grid-cols-4 gap-8 md:gap-16 mt-12">
          {stats.map((stat, i) => (
            <div key={i} className="text-center lg:text-left">
              <div className="font-mono text-5xl md:text-6xl lg:text-7xl font-bold text-[#A3FF3F]">
                <AnimatedNumber target={stat.value} suffix={stat.suffix} />
              </div>
              <div className="mt-3 text-sm text-[#8B8B8B] uppercase tracking-widest">
                {stat.label}
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
